/**
 * Turns the per-run JSON files into docs/scale/main-1000-baseline.md and a
 * machine-readable copy. Every number carries a measured / derived label: see
 * "How to read these numbers" in the generated file.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import type { RunResult } from './baseline';
import type { PhaseCost } from './metrics';
import { relativeDifference } from './metrics';
import { metricsOf, round } from './reportMetrics';
import { renderMethod } from './reportMethod';

const FULL_RUN_LABELS = ['run1', 'run2'];
const TOLERANCE_PERCENT = 10;
/** A later comparison run writes under its own name so the baseline stays as it was. */
const REPORT_NAME = process.env.SCALE_REPORT_NAME ?? 'main-1000-baseline';

function loadRun(outDir: string, label: string): RunResult {
	return JSON.parse(readFileSync(path.join(outDir, `${label}.json`), 'utf8')) as RunResult;
}

function collectionList(counts: Record<string, number>): string {
	return Object.entries(counts)
		.sort(([, a], [, b]) => b - a)
		.map(([name, count]) => `${name} ${count}`)
		.join(', ');
}

function fieldChanges(run: RunResult): string {
	const changes = run.clients[0]?.questionFieldChanges ?? {};
	const lines = run.phases.map(
		(phase) => `| ${phase.name} | ${collectionList(changes[phase.name] ?? {}) || 'none'} |`,
	);

	return ['| phase | question doc fields changed (snapshots seen) |', '|---|---|', ...lines].join(
		'\n',
	);
}

function phaseTable(phase: PhaseCost): string {
	const lines = Object.entries(phase.byFunction)
		.sort(([, a], [, b]) => b.invocations - a.invocations)
		.map(
			([fn, cost]) =>
				`| ${fn} | ${cost.invocations} | ${cost.meanMs} | ${cost.p95Ms} | ${cost.docsRead} | ${cost.docsWritten} |`,
		);

	return [
		`**${phase.name}** (${phase.units} units, ${phase.invocationsTotal} invocations, ${phase.totalReads} docs read, ${phase.totalWrites} docs written, ${phase.failedCommits} failed commits)`,
		'',
		`Reads by collection: ${collectionList(phase.readsByCollection) || 'none'}.`,
		'',
		`Writes by collection: ${collectionList(phase.writesByCollection) || 'none'}.`,
		'',
		`Writes landing after the trigger returned: ${collectionList(phase.writesAfterReturn) || 'none'}.`,
		'',
		`Question document writes (function: fields): ${collectionList(phase.questionWriters) || 'none'}.`,
		'',
		'| trigger | invocations | mean ms | p95 ms | docs read | docs written |',
		'|---|---:|---:|---:|---:|---:|',
		...lines,
		'',
	].join('\n');
}

function metricTable(primary: RunResult, others: RunResult[]): string {
	const rowsByKey = others.map((run) => new Map(metricsOf(run).map((row) => [row.key, row])));
	const header = others.map((run) => run.label).join(' | ');

	return [
		`| metric | ${primary.label} | ${header} | kind | note |`,
		`|---|---:|${others.map(() => '---:').join('|')}|---|---|`,
		...metricsOf(primary).map((row) => {
			const cells = rowsByKey.map((map) => map.get(row.key)?.value ?? '');

			return `| ${row.label} | ${row.value} | ${cells.join(' | ')} | ${row.kind} | ${row.note ?? ''} |`;
		}),
	].join('\n');
}

function stabilityTable(a: RunResult, b: RunResult): { markdown: string; worstPercent: number } {
	const rowsB = new Map(metricsOf(b).map((row) => [row.key, row]));
	const entries = metricsOf(a)
		.filter((row) => row.kind === 'measured' && !row.key.endsWith('Ms') && !row.key.includes('ms'))
		.map((row) => {
			const other = rowsB.get(row.key)?.value ?? 0;

			return {
				label: row.label,
				a: row.value,
				b: other,
				percent: round(relativeDifference(row.value, other) * 100),
			};
		});
	const worst = entries.reduce((max, entry) => Math.max(max, entry.percent), 0);
	const lines = entries.map(
		(entry) =>
			`| ${entry.label} | ${entry.a} | ${entry.b} | ${entry.percent}%${entry.percent > TOLERANCE_PERCENT ? ' (over tolerance)' : ''} |`,
	);

	return {
		worstPercent: worst,
		markdown: [
			`| metric | ${a.label} | ${b.label} | difference |`,
			'|---|---:|---:|---:|',
			...lines,
		].join('\n'),
	};
}

function main(): void {
	const outDir = process.env.SCALE_OUT_DIR;
	if (!outDir) throw new Error('SCALE_OUT_DIR must be set');
	const [run1, run2] = FULL_RUN_LABELS.map((label) => loadRun(outDir, label));
	const small = loadRun(outDir, 'small');
	const stability = stabilityTable(run1, run2);

	const markdown = [
		'# Main app scale baseline: one question at about 1,000 participants (task 3.0)',
		'',
		`Generated by \`npm run scale:baseline\` on ${run1.date.slice(0, 10)}, commit \`${run1.commit}\`.`,
		`Sizes: full = ${run1.config.members} subscribers and ${run1.config.answers} answers; small = ${small.config.members} and ${small.config.answers}.`,
		'',
		'## Baseline numbers',
		'',
		metricTable(run1, [run2, small]),
		'',
		'## Answers rated, by age (exposure)',
		'',
		`Model: answers arrive over the first ${70}% of ${run1.config.members} arriving people; up to 30 answers each person rates the first ${run1.config.ratingsPerMember} cards of the app's newest-30 query; above 30 they rate the sampler's batches, ${run1.config.ratingsPerMember} ratings each.`,
		'',
		'| | oldest quarter | second | third | newest quarter | rated at all | unrated |',
		'|---|---:|---:|---:|---:|---:|---:|',
		`| rate ${run1.config.ratingsPerMember} of shown | ${run1.exposure.stats.meanByAgeQuarter.join(' | ')} | ${run1.exposure.stats.ratedAnswers} | ${run1.exposure.stats.unratedAnswers} |`,
		`| rated every card shown (upper bound) | ${run1.exposure.ifRatedWholeWindow.meanByAgeQuarter.join(' | ')} | ${run1.exposure.ifRatedWholeWindow.ratedAnswers} | ${run1.exposure.ifRatedWholeWindow.unratedAnswers} |`,
		'',
		'## What changes the question document (one sample listener, first full run)',
		'',
		fieldChanges(run1),
		'',
		'## Function invocations per phase (full size, first run)',
		'',
		...run1.phases.map(phaseTable),
		'## Stability between the two full runs',
		'',
		`Stated tolerance: ${TOLERANCE_PERCENT}% for measured counts. Worst difference: ${stability.worstPercent}%. Timings are excluded: they depend on the machine.`,
		'',
		stability.markdown,
		'',
		renderMethod(run1, small),
		'',
	].join('\n');

	const docsDir = path.join(process.cwd(), 'docs', 'scale');
	mkdirSync(docsDir, { recursive: true });
	writeFileSync(path.join(docsDir, `${REPORT_NAME}.md`), markdown);
	writeFileSync(
		path.join(docsDir, `${REPORT_NAME}.data.json`),
		JSON.stringify({ run1, run2, small }, null, 2),
	);
	console.info(`[scale] report written; worst difference between runs: ${stability.worstPercent}%`);
}

if (process.argv[1]?.endsWith('report.ts')) main();
